Action: write with {"path":"src/lib/resolvers.ts","content":"/**
 * TUI-specific impulse resolvers for minibob-tui
 */

import { BaseResolver } from "./impulse-resolver.ts";
import type { ResolverContext, ResolverResult } from "./impulse-resolver.ts";
import { ResolverRegistry } from "./resolver-registry.ts";
import type { Impulse, Region } from "../types.ts";
import { getTUIState } from "./state.ts";

/**
 * Pending confirmation state
 */
interface PendingConfirmation {
  impulseId: string;
  resolve: (accepted: boolean) => void;
  reject: (error: Error) => void;
}

/**
 * Resolver for user_input shape impulses
 */
export class TUIInputResolver extends BaseResolver {
  readonly name = "tui-input";
  readonly supportedTypes = ["user_input"] as const;
  readonly priority = 200;

  canResolve(impulse: Impulse): boolean {
    return impulse.metadata?.shape === "user_input" || super.canResolve(impulse);
  }

  async resolve(context: ResolverContext): Promise<ResolverResult> {
    try {
      const tuiState = getTUIState();
      const inputState = tuiState.getInputState();

      return this.success({
        value: inputState.value,
        active: inputState.active,
        cursorPosition: inputState.cursorPosition,
      });
    } catch (error) {
      return this.error(
        error instanceof Error ? error.message : "Failed to resolve user input"
      );
    }
  }
}

/**
 * Resolver for user_confirmation shape impulses
 */
export class TUIDialogResolver extends BaseResolver {
  readonly name = "tui-dialog";
  readonly supportedTypes = ["user_confirmation"] as const;
  readonly priority = 200;

  private pendingConfirmations = new Map<string, PendingConfirmation>();

  canResolve(impulse: Impulse): boolean {
    return impulse.metadata?.shape === "user_confirmation" || super.canResolve(impulse);
  }

  async resolve(context: ResolverContext): Promise<ResolverResult> {
    try {
      const { impulse } = context;
      const message = (impulse.content as any)?.message || "Confirm action?";

      const confirmationPromise = new Promise<boolean>((resolve, reject) => {
        this.pendingConfirmations.set(impulse.id, {
          impulseId: impulse.id,
          resolve,
          reject,
        });
      });

      const accepted = await confirmationPromise;

      return this.success({
        message,
        accepted,
        timestamp: Date.now(),
      });
    } catch (error) {
      const { impulse } = context;
      this.pendingConfirmations.delete(impulse.id);

      return this.error(
        error instanceof Error ? error.message : "Failed to resolve user confirmation"
      );
    }
  }

  respondToConfirmation(impulseId: string, accepted: boolean): boolean {
    const pending = this.pendingConfirmations.get(impulseId);
    if (!pending) {
      return false;
    }

    this.pendingConfirmations.delete(impulseId);
    pending.resolve(accepted);
    return true;
  }

  cancelConfirmation(impulseId: string): boolean {
    const pending = this.pendingConfirmations.get(impulseId);
    if (!pending) {
      return false;
    }

    this.pendingConfirmations.delete(impulseId);
    pending.reject(new Error("Confirmation cancelled"));
    return true;
  }

  getPendingConfirmations(): string[] {
    return Array.from(this.pendingConfirmations.keys());
  }

  async dispose(): Promise<void> {
    for (const [impulseId] of this.pendingConfirmations) {
      this.cancelConfirmation(impulseId);
    }
    await super.dispose();
  }
}

/**
 * Resolver for region inspection impulses
 */
export class TUIRegionResolver extends BaseResolver {
  readonly name = "tui-region";
  readonly supportedTypes = ["region_query", "region_inspection"] as const;
  readonly priority = 200;

  canResolve(impulse: Impulse): boolean {
    return (
      impulse.metadata?.shape === "region_inspection" ||
      impulse.pointer.type === "region_query" ||
      super.canResolve(impulse)
    );
  }

  async resolve(context: ResolverContext): Promise<ResolverResult> {
    try {
      const { impulse } = context;
      const tuiState = getTUIState();
      const regionManager = tuiState.getRegionManager();

      const regionId = (impulse.content as any)?.regionId;

      if (regionId) {
        const region = regionManager.get(regionId);
        if (!region) {
          return this.error(`Region not found: ${regionId}`);
        }

        return this.success({
          region: this.serializeRegion(region),
          timestamp: Date.now(),
        });
      } else {
        const regions = regionManager.getAll();
        const layout = tuiState.getLayout();

        return this.success({
          regions: regions.map(r => this.serializeRegion(r)),
          layout: layout.map(r => this.serializeRegion(r)),
          count: regions.length,
          timestamp: Date.now(),
        });
      }
    } catch (error) {
      return this.error(
        error instanceof Error ? error.message : "Failed to resolve region inspection"
      );
    }
  }

  private serializeRegion(region: Region): any {
    return {
      impulseId: region.impulseId,
      impulse: {
        id: region.impulse.id,
        pointer: region.impulse.pointer,
        metadata: region.impulse.metadata,
        loaded: region.impulse.loaded,
        priority: region.impulse.priority,
      },
      layout: region.layout,
      state: region.state,
      componentType: region.componentType,
    };
  }
}

/**
 * Create and configure a TUI resolver registry with all TUI resolvers
 */
export function createTUIResolverRegistry(): ResolverRegistry {
  const registry = new ResolverRegistry();

  registry.register(new TUIInputResolver());
  registry.register(new TUIDialogResolver());
  registry.register(new TUIRegionResolver());

  return registry;
}
