Create file: minibob-tracer.ts
```typescript
/**
 * MiniBob Runtime Tracer
 * Captures function executions as activity traces
 */

const MCP_ENDPOINT = process.env.MCP_ENDPOINT || 'http://activity.metabob.local';
const AUTH_TOKEN = process.env.MINIBOB_AUTH_TOKEN;

interface TraceContext {
  activityId: string;
  parentId?: string;
  startTime: number;
  args: unknown[];
  metadata: Record<string, unknown>;
}

const activeTraces = new Map<string, TraceContext>();

export function startTrace(
  functionName: string,
  args: unknown[],
  metadata: Record<string, unknown> = {}
): string {
  const traceId = `trace_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const activityId = `${metadata.prefix || 'traced'}-${functionName}`;

  activeTraces.set(traceId, {
    activityId,
    parentId: metadata.parentTraceId as string | undefined,
    startTime: Date.now(),
    args,
    metadata
  });

  return traceId;
}

export async function endTrace(
  traceId: string,
  result: { success: boolean; value?: unknown; error?: Error }
): Promise<void> {
  const ctx = activeTraces.get(traceId);
  if (!ctx) return;

  activeTraces.delete(traceId);

  const duration = Date.now() - ctx.startTime;

  const trace = {
    execution_id: traceId,
    activity_id: ctx.activityId,
    variant_id: ctx.activityId,
    success: result.success,
    status: result.success ? 'success' : 'failure',
    duration_ms: duration,
    input_impulse_shapes: ctx.args.map((arg, i) => ({
      shape: `arg_${i}`,
      type: typeof arg
    })),
    output_impulse_shapes: result.value ? [{
      shape: 'return_value',
      type: typeof result.value
    }] : [],
    state_snapshot: {
      input_state: { arguments: ctx.args },
      output_state: { returnValue: result.value, error: result.error?.message }
    },
    error_message: result.error?.message,
    parent_execution_id: ctx.parentId,
    executed_at: new Date(ctx.startTime).toISOString()
  };

  // Fire and forget - don't block execution
  if (MCP_ENDPOINT && AUTH_TOKEN) {
    fetch(`${MCP_ENDPOINT}/v2/activities/execution-traces`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${AUTH_TOKEN}`
      },
      body: JSON.stringify(trace)
    }).catch(() => {}); // Ignore errors
  }
}

export function traced<T extends (...args: any[]) => any>(
  fn: T,
  name?: string,
  metadata: Record<string, unknown> = {}
): T {
  const fnName = name || fn.name || 'anonymous';

  return (async (...args: Parameters<T>) => {
    const traceId = startTrace(fnName, args, metadata);

    try {
      const result = await fn(...args);
      await endTrace(traceId, { success: true, value: result });
      return result;
    } catch (error) {
      await endTrace(traceId, { success: false, error: error as Error });
      throw error;
    }
  }) as T;
}

export default { startTrace, endTrace, traced };
```

