import type { Impulse, Region } from "../types.ts";
import { getTUIState } from "./state.ts";

/**
 * Result of impulse resolution
 */
export interface ResolvedImpulse {
  content: unknown;
  success: boolean;
  error?: string;
}

/**
 * Interface for TUI impulse resolvers
 */
export interface ImpulseResolver {
  resolve(impulse: Impulse): Promise<ResolvedImpulse>;
  supports(impulse: Impulse): boolean;
}

/**
 * Resolver for user_input shape impulses
 */
export class TUIInputResolver implements ImpulseResolver {
  supports(impulse: Impulse): boolean {
    return impulse.metadata?.shape === "user_input";
  }

  async resolve(impulse: Impulse): Promise<ResolvedImpulse> {
    try {
      const tuiState = getTUIState();
      const inputState = tuiState.getInputState();

      return {
        content: {
          value: inputState.value,
          active: inputState.active,
          cursorPosition: inputState.cursorPosition,
        },
        success: true,
      };
    } catch (error) {
      return {
        content: null,
        success: false,
        error: error instanceof Error ? error.message : "Failed to resolve user input",
      };
    }
  }
}
"}

