/**
 * Registry for managing TUI impulse resolvers
 */
export class ResolverRegistry {
  private resolvers: ImpulseResolver[] = [];

  registerResolver(resolver: ImpulseResolver): void {
    this.resolvers.push(resolver);
  }

  async resolve(impulse: Impulse): Promise<ResolvedImpulse> {
    for (const resolver of this.resolvers) {
      if (resolver.supports(impulse)) {
        return await resolver.resolve(impulse);
      }
    }

    return {
      content: null,
      success: false,
      error: `No resolver found for impulse shape: ${impulse.metadata?.shape || impulse.pointer.type}`,
    };
  }

  getResolvers(): ImpulseResolver[] {
    return [...this.resolvers];
  }

  clear(): void {
    this.resolvers = [];
  }
}

/**
 * Default registry with all TUI resolvers registered
 */
const defaultRegistry = new ResolverRegistry();
defaultRegistry.registerResolver(new TUIInputResolver());
defaultRegistry.registerResolver(new TUIDialogResolver());
defaultRegistry.registerResolver(new TUIRegionResolver());

export default defaultRegistry;
EOF"}

